I have a producer-consumer setup using pthreads and a circular buffer, but it deadlocks intermittently under load. Can you review my mutex/condvar logic and find the race?

typedef struct {
    int buf[16];
    int head, tail, count;
    pthread_mutex_t lock;
    pthread_cond_t not_full, not_empty;
} ring_t;

void push(ring_t *r, int val) {
    pthread_mutex_lock(&r->lock);
    while (r->count == 16) pthread_cond_wait(&r->not_full, &r->lock);
    r->buf[r->tail] = val;
    r->tail = (r->tail + 1) % 16;
    r->count++;
    pthread_cond_signal(&r->not_empty);
    pthread_mutex_unlock(&r->lock);
}
